def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    adv_gap = batch['advantage_gap']
    pred_margin = ops.sub(lpw, lpl)
    error = ops.sub(pred_margin, adv_gap)
    abs_error = ops.abs(error)
    if weight is not None:
        weighted_error = ops.mul(abs_error, weight)
    else:
        weighted_error = abs_error
    return ops.mean(weighted_error)
